CREATE DATABASE IF NOT EXISTS yakap CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE yakap;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(150) NOT NULL,role ENUM('Admin','Pharmacist','Encoder') NOT NULL DEFAULT 'Encoder',status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE patients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_code VARCHAR(50) NOT NULL UNIQUE,philhealth_id VARCHAR(30) NOT NULL,first_name VARCHAR(80) NOT NULL,middle_name VARCHAR(80) NULL,last_name VARCHAR(80) NOT NULL,birthdate DATE NOT NULL,sex ENUM('Male','Female','Other') NOT NULL,address VARCHAR(255) NULL,contact_number VARCHAR(30) NULL,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_philhealth (philhealth_id)) ENGINE=InnoDB;
CREATE TABLE medical_records (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id INT UNSIGNED NOT NULL,diagnosis TEXT,physician VARCHAR(150),notes TEXT,record_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,created_by INT UNSIGNED NULL,FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE,FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE medicines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,medicine_name VARCHAR(150) NOT NULL,generic_name VARCHAR(150),dosage_form VARCHAR(80),unit_price DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE medicine_inventory (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,medicine_id INT UNSIGNED NOT NULL UNIQUE,quantity INT NOT NULL DEFAULT 0,reorder_level INT NOT NULL DEFAULT 10,FOREIGN KEY (medicine_id) REFERENCES medicines(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE medicine_stock_movements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,medicine_id INT UNSIGNED NOT NULL,movement_type ENUM('IN','OUT','ADJUSTMENT') NOT NULL,quantity INT NOT NULL,batch_number VARCHAR(80),expiration_date DATE NULL,remarks VARCHAR(255),user_id INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (medicine_id) REFERENCES medicines(id) ON DELETE CASCADE,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE medicine_purchases (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_no VARCHAR(40) NOT NULL UNIQUE,patient_id INT UNSIGNED NOT NULL,pharmacist_id INT UNSIGNED NULL,total_amount DECIMAL(12,2) NOT NULL DEFAULT 0,reference_no VARCHAR(80),purchase_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (patient_id) REFERENCES patients(id),FOREIGN KEY (pharmacist_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE medicine_purchase_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_id INT UNSIGNED NOT NULL,medicine_id INT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,total_price DECIMAL(12,2) NOT NULL,FOREIGN KEY (purchase_id) REFERENCES medicine_purchases(id) ON DELETE CASCADE,FOREIGN KEY (medicine_id) REFERENCES medicines(id)) ENGINE=InnoDB;
CREATE TABLE backup_records (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,filename VARCHAR(255) NOT NULL,file_size BIGINT UNSIGNED NOT NULL DEFAULT 0,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,action VARCHAR(50) NOT NULL,module VARCHAR(80) NOT NULL,record_id VARCHAR(80),details TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
